                interface = sys.argv[2]
        elif arg == '-f':
            if len(sys.argv) >=2:
                filter = sys.argv[2]
        elif arg == '-m':
            if len(sys.argv) >=2:
                action = sys.argv[2]
        elif arg == '-o':
            if len(sys.argv) >=2:
                filename = sys.argv[2]
        else:
            pass

    # Define actions: modify, drop, redirect
    def modify_packet(packet, action):
        if action == 'modify':
            # Example: Modify packet contents
            # This is a simple example; modify as needed
            return packet
        elif action == 'drop':
            return None
        elif action == 'redirect':
            # Redirect to a different port or host
            return packet
        else:
            return packet

    # Start sniffer
    sniffer = Sniffer(filter=filter, store=0)
    try:
        for packet in sniffer:
            if IP in packet:
                # Process each IP packet
                if action == 'modify':
                    modified_packet = modify_packet(packet, action)
                    if modified_packet:
                        print(f"Modified packet: {modified_packet}")
                elif action == 'drop':
                    print("Dropped packet: {packet}")
                elif action == 'redirect':
                    print("Redirecting packet: {packet}")
    except KeyboardInterrupt:
        print("\nIntercepted and modified traffic stopped.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
